    }

    /// <summary>types of state on the surface</summary>
    public enum State : uint
    {
        /// <summary>the surface is maximized</summary>
        Maximized = 1,
        /// <summary>the surface is fullscreen</summary>
        Fullscreen = 2,
        /// <summary>the surface is being resized</summary>
        Resizing = 3,
        /// <summary>the surface is now activated</summary>
        Activated = 4,
        TiledLeft = 5,
        TiledRight = 6,
        TiledTop = 7,
        TiledBottom = 8,
        Suspended = 9,
        ConstrainedLeft = 10,
        ConstrainedRight = 11,
        ConstrainedTop = 12,
        ConstrainedBottom = 13,
    }

    public enum WmCapabilities : uint
    {
        /// <summary>show_window_menu is available</summary>
        WindowMenu = 1,
        /// <summary>set_maximized and unset_maximized are available</summary>
        Maximize = 2,
        /// <summary>set_fullscreen and unset_fullscreen are available</summary>
        Fullscreen = 3,
        /// <summary>set_minimized is available</summary>
        Minimize = 4,
