    /// <summary>
    /// struct xdg_toplevel_listener: one unmanaged function pointer per event, in opcode order.
    /// Each handler is <c>[UnmanagedCallersOnly]</c> and gets the listener's data pointer and the
    /// proxy first. A destructor event's handler must destroy the proxy (<see cref="DestroyProxy"/>).
    /// </summary>
    [StructLayout(LayoutKind.Sequential)]
    public struct Listener
    {
        /// <summary>suggest a surface change</summary>
        public delegate* unmanaged<void*, XdgToplevel, int, int, WlArray*, void> Configure;
        /// <summary>surface wants to be closed</summary>
        public delegate* unmanaged<void*, XdgToplevel, void> Close;
