        /// <remarks>Since version 4.</remarks>
        public delegate* unmanaged<void*, XdgToplevel, int, int, void> ConfigureBounds;
        public const uint ConfigureBoundsSince = 4;
        /// <summary>compositor capabilities</summary>
        /// <remarks>Since version 5.</remarks>
        public delegate* unmanaged<void*, XdgToplevel, WlArray*, void> WmCapabilities;
        public const uint WmCapabilitiesSince = 5;

        /// <summary>
        /// Copies <paramref name="handlers"/> into native memory, filling every slot left null with a
        /// handler that does nothing (or, for a destructor event, only destroys the proxy): libwayland
        /// calls an event's slot without checking it. The copy lives until <see cref="Free"/>.
        /// </summary>
        public static Listener* Create(in Listener handlers)
        {
            var l = (Listener*)NativeMemory.Alloc((nuint)sizeof(Listener));
            *l = handlers;
            if (l->Configure == null) l->Configure = &Defaults.Configure;
            if (l->Close == null) l->Close = &Defaults.Close;
            if (l->ConfigureBounds == null) l->ConfigureBounds = &Defaults.ConfigureBounds;
            if (l->WmCapabilities == null) l->WmCapabilities = &Defaults.WmCapabilities;
            return l;
        }

        public static void Free(Listener* listener) => NativeMemory.Free(listener);
    }

    /// <summary>The handlers <see cref="Listener.Create"/> puts in a slot left empty.</summary>
    public static class Defaults
    {
        [UnmanagedCallersOnly]
        public static void Configure(void* data, XdgToplevel self, int width, int height, WlArray* states) { }
        [UnmanagedCallersOnly]
        public static void Close(void* data, XdgToplevel self) { }
        [UnmanagedCallersOnly]
        public static void ConfigureBounds(void* data, XdgToplevel self, int width, int height) { }
        [UnmanagedCallersOnly]
        public static void WmCapabilities(void* data, XdgToplevel self, WlArray* capabilities) { }
    }
}

/// <summary>short-lived, popup surfaces for menus</summary>
internal readonly unsafe partial record struct XdgPopup(nint Handle) : IWlProxy<XdgPopup>
{
    public const string InterfaceName = "xdg_popup";
    public const uint InterfaceVersion = 7;

    public static WlInterface* Interface => WaylandInterfaces.xdg_popup;
    static uint IWlProxy<XdgPopup>.MaxVersion => InterfaceVersion;
    public static XdgPopup FromHandle(nint handle) => new(handle);

    public bool IsNull => Handle == 0;

    // Not the record's default, which would read Version — a native call — on a possibly dead proxy.
    public override string ToString() => $"{InterfaceName}@{Handle:x}";

    /// <summary>The version this object was created at.</summary>
    public uint Version => WaylandNative.wl_proxy_get_version(Handle);

    /// <summary>Frees the client-side proxy without telling the compositor (wl_proxy_destroy).</summary>
    public void DestroyProxy() => WaylandNative.wl_proxy_destroy(Handle);

    /// <summary>Sets the listener; <paramref name="listener"/> must outlive the object (see <see cref="Listener.Create"/>).</summary>
    public int AddListener(Listener* listener, void* data = null) => WaylandNative.wl_proxy_add_listener(Handle, listener, data);

    public const uint DestroyOpcode = 0;
    /// <summary>remove xdg_popup interface</summary>
    /// <remarks>Destroys the object.</remarks>
    public void Destroy()
    {
        uint v = WaylandNative.wl_proxy_get_version(Handle);
        WlArgument* a = stackalloc WlArgument[1];
        WaylandNative.wl_proxy_marshal_array_flags(Handle, 0, null, v, WaylandNative.WL_MARSHAL_FLAG_DESTROY, a);
    }

    public const uint GrabOpcode = 1;
    /// <summary>make the popup take an explicit grab</summary>
    public void Grab(WlSeat seat, uint serial)
    {
        uint v = WaylandNative.wl_proxy_get_version(Handle);
        WlArgument* a = stackalloc WlArgument[2];
        a[0].O = seat.Handle;
        a[1].U = serial;
        WaylandNative.wl_proxy_marshal_array_flags(Handle, 1, null, v, 0, a);
    }

    public const uint RepositionOpcode = 2;
    public const uint RepositionSince = 3;
    /// <summary>recalculate the popup's location</summary>
    /// <remarks>Since version 3.</remarks>
    public void Reposition(XdgPositioner positioner, uint token)
    {
        uint v = WaylandNative.wl_proxy_get_version(Handle);
        if (v < 3) throw WaylandNative.TooOld("xdg_popup.reposition", 3, v);
        WlArgument* a = stackalloc WlArgument[2];
        a[0].O = positioner.Handle;
        a[1].U = token;
        WaylandNative.wl_proxy_marshal_array_flags(Handle, 2, null, v, 0, a);
    }

    public enum Error : uint
    {
        /// <summary>tried to grab after being mapped</summary>
        InvalidGrab = 0,
    }

    /// <summary>
    /// struct xdg_popup_listener: one unmanaged function pointer per event, in opcode order.
    /// Each handler is <c>[UnmanagedCallersOnly]</c> and gets the listener's data pointer and the
    /// proxy first. A destructor event's handler must destroy the proxy (<see cref="DestroyProxy"/>).
    /// </summary>
    [StructLayout(LayoutKind.Sequential)]
    public struct Listener
    {
        /// <summary>configure the popup surface</summary>
        public delegate* unmanaged<void*, XdgPopup, int, int, int, int, void> Configure;
        /// <summary>popup interaction is done</summary>
        public delegate* unmanaged<void*, XdgPopup, void> PopupDone;
        /// <summary>signal the completion of a repositioned request</summary>
        /// <remarks>Since version 3.</remarks>
        public delegate* unmanaged<void*, XdgPopup, uint, void> Repositioned;
        public const uint RepositionedSince = 3;

        /// <summary>
        /// Copies <paramref name="handlers"/> into native memory, filling every slot left null with a
        /// handler that does nothing (or, for a destructor event, only destroys the proxy): libwayland
        /// calls an event's slot without checking it. The copy lives until <see cref="Free"/>.
        /// </summary>
        public static Listener* Create(in Listener handlers)
        {
